topics.description:
A **function** is a reusable block of code that performs a task. Without functions you would copy and paste the same lines everywhere.

### Ways to create a function
```js
// 1. Declaration (hoisted)
function add(a, b) { return a + b; }

// 2. Expression (not hoisted for use before definition)
const multiply = function (a, b) { return a * b; };

// 3. Named function expression
const fact = function f(n) { return n <= 1 ? 1 : n * f(n - 1); };

// 4. Arrow function (see next topic)
const sub = (a, b) => a - b;
```

### Parameters vs arguments
- **Parameters** are the names listed in the definition.
- **Arguments** are the actual values passed when calling.
- Missing arguments become `undefined`; extra arguments are ignored (but available through `arguments` or rest).

### return
`return` sends a value back to the caller and **stops** the function. A function without `return` returns `undefined`. Do not put a line break right after `return`, because automatic semicolon insertion turns it into `return;`.

### Functions are values
A function is an object. You can store it in a variable, put it in an array, pass it to another function or return it from one (first-class functions).

### Function declaration vs expression
Declarations are **hoisted completely**, so you can call them before they appear in the file. Expressions assigned with `let`/`const` cannot be used before the line runs.

Each call creates a new **local scope**, so variables inside are not visible outside.

examples.code:
console.log(sum(5, 10));      // works: declarations are hoisted

function sum(a, b) {
  return a + b;
  console.log("never printed");
}

const greet = function (name) {
  return "Hello " + name + ", welcome to the JS course";
};
console.log(greet("Ravi"));
console.log(typeof noReturn(), typeof sum);

function noReturn() {}

try {
  later();
} catch (e) {
  console.log(e.name);
}
const later = () => "ok";

const reverse = (str) => {
  let out = "";
  for (let i = str.length - 1; i >= 0; i--) out += str[i];
  return out;
};
const isPalindrome = (str) => str === reverse(str);

console.log(reverse("vinod thapa"));
console.log(isPalindrome("level"), isPalindrome("hello"));

const counter = {
  count: 0,
  startNormal() {
    setTimeout(function () {
      console.log("normal this.count:", this === counter, this.count);
    }, 0);
  },
  startArrow() {
    setTimeout(() => {
      console.log("arrow this.count:", this.count);
    }, 0);
  },
};
counter.count = 7;
counter.startNormal();
counter.startArrow();

const makeUser = (name) => ({ name });
console.log(makeUser("Asha"));

function sum(a = 20, b = 10) { return a + b; }
console.log(sum(), sum(1), sum(undefined, 5), sum(null, 5));

const total = (a, b, ...nums) => nums.reduce((x, y) => x + y, a + b);
console.log(total(1, 2, 3, 4));

const nums = [4, 9, 2];
console.log(Math.max(...nums), Math.min(...nums));

function legacy() { return arguments.length + " args, array? " + Array.isArray(arguments); }
console.log(legacy(1, 2, 3));

function createUser({ name, role = "user" } = {}) { return `${name ?? "anon"}:${role}`; }
console.log(createUser({ name: "Ravi" }), createUser());

const bank = (function () {
  let balance = 100;           // private
  return {
    deposit(n) { balance += n; return balance; },
    getBalance() { return balance; },
  };
})();

console.log(bank.deposit(50));
console.log(bank.getBalance());
console.log(bank.balance);     // undefined - private

const result = (function (a, b) { return a + b; })(5, 10);
console.log("sum:", result);

(async () => {
  const v = await Promise.resolve("async IIFE done");
  console.log(v);
})();

const add = (a, b) => a + b;
const sub = (a, b) => b - a;
const mathOperation = (a, b, operation) => operation(a, b);
console.log(mathOperation(5, 15, add));
console.log(mathOperation(5, 15, sub));

const multiplier = (factor) => (number) => number * factor;
const double = multiplier(2), triple = multiplier(3);
console.log(double(5), triple(5));

function processUserInput(name, callback) {
  console.log("Received:", name);
  callback(name);
}
processUserInput("Vinod", (n) => console.log(`Hello! ${n}`));

const impure = (arr, x) => { arr.push(x); return arr; };
const pure = (arr, x) => [...arr, x];
const base = [1, 2];
console.log(pure(base, 3), base);
impure(base, 99);
console.log(base);

const curry = (fn) => function curried(...args) {
  return args.length >= fn.length
    ? fn(...args)
    : (...rest) => curried(...args, ...rest);
};
const volume = curry((l, w, h) => l * w * h);
console.log(volume(2)(3)(4), volume(2, 3)(4));

const pipe = (...fns) => (x) => fns.reduce((v, f) => f(v), x);
const slugify = pipe(
  (s) => s.trim(),
  (s) => s.toLowerCase(),
  (s) => s.replace(/\s+/g, "-")
);
console.log(slugify("  Learn JavaScript Fast "));

const factorial = (n) => (n <= 1 ? 1 : n * factorial(n - 1));
console.log(factorial(5));

const sumDeep = (arr) =>
  arr.reduce((acc, v) => acc + (Array.isArray(v) ? sumDeep(v) : v), 0);
console.log(sumDeep([1, [2, [3, 4]], 5]));

const memo = new Map();
function fib(n) {
  if (n < 2) return n;
  if (memo.has(n)) return memo.get(n);
  const value = fib(n - 1) + fib(n - 2);
  memo.set(n, value);
  return value;
}
console.log(fib(50));

try {
  (function forever() { forever(); })();
} catch (e) {
  console.log(e.name);
}
